+#define MBOX_DEVICE_BUSY (0x03U)
+#define MBOX_DEVICE_DONE (0x04U)
+#define MBOX_DEVICE_STOP (0x0FU)
+#define MBOX_DEVICE_LOGLVL (0x10U)
+#define MBOX_HOST_READY (0x1000U)
+#define MBOX_HOST_DONE (0x3000U)
