+/**
+ * @brief Holds physical addresses of the shared L3
+ * @a2h_rb: accelerator to host ring buffer
+ * @head: base of heap memory
+ */
+struct l3_layout {
+    uint32_t a2h_rb;
+    uint32_t a2h_mbox;
+    uint32_t h2a_mbox;
+    uint32_t heap;
+};
